<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { Pencil, Plus, Trash2, UserRound } from 'lucide-vue-next'
import { watchDebounced } from '@vueuse/core'
import type { AdminPlayer, AdminPlayerInput, AdminPlayersResponse, AdminTeamsResponse } from '@@/types/admin-club'
definePageMeta({ allowedRoles: ['admin'] })
const selectClass = 'flex min-h-[44px] w-full rounded-lg border border-input bg-surface px-3 py-2 text-sm text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-400'
const searchInput = ref(''); const search = ref(''); const teamFilter = ref('all'); const selectedPlayerId = ref<string | null>(null); const isSubmitting = ref(false); const deletingPlayerId = ref<string | null>(null); const pageError = ref<string | null>(null); const pageSuccess = ref<string | null>(null)
type PlayerForm = Omit<AdminPlayerInput, 'shirt_number'> & { shirt_number: string | number }
const form = reactive<PlayerForm>({ full_name: '', shirt_number: '', date_of_birth: '', team_id: '', is_active: true })
watchDebounced(searchInput, value => { search.value = value.trim() }, { debounce: 300, maxWait: 900 })
const { data: teamData } = await useFetch<AdminTeamsResponse>('/api/admin/teams', { default: () => ({ teams: [] }) }); const { data: playerData, pending, refresh } = await useFetch<AdminPlayersResponse>('/api/admin/players', { query: computed(() => ({ q: search.value, team_id: teamFilter.value })), default: () => ({ players: [] }) })
const teams = computed(() => teamData.value?.teams ?? []); const activeTeams = computed(() => teams.value.filter(team => team.is_active)); const players = computed(() => playerData.value?.players ?? []); const selectedPlayer = computed(() => players.value.find(player => player.id === selectedPlayerId.value) ?? null); const isCreateMode = computed(() => !selectedPlayer.value)
function resetForm() { selectedPlayerId.value = null; Object.assign(form, { full_name: '', shirt_number: '', date_of_birth: '', team_id: activeTeams.value[0]?.id ?? '', is_active: true }); pageError.value = null }
function editPlayer(player: AdminPlayer) { selectedPlayerId.value = player.id; Object.assign(form, { full_name: player.full_name, shirt_number: player.shirt_number ?? '', date_of_birth: player.date_of_birth, team_id: player.team_id, is_active: player.is_active }); pageError.value = null }
function report(error: unknown, fallback: string) { const details = error as { data?: { statusMessage?: string }, message?: string }; pageError.value = details.data?.statusMessage || details.message || fallback }
async function submitForm() { pageError.value = null; pageSuccess.value = null; isSubmitting.value = true; try { const payload = { ...form, full_name: form.full_name.trim(), shirt_number: form.shirt_number === '' ? null : form.shirt_number }; if (selectedPlayer.value) { await $fetch(`/api/admin/players/${selectedPlayer.value.id}`, { method: 'PATCH', body: payload }); pageSuccess.value = 'Player updated.' } else { await $fetch('/api/admin/players', { method: 'POST', body: payload }); pageSuccess.value = 'Player created.' }; await refresh(); resetForm() } catch (error) { report(error, 'Unable to save the player.') } finally { isSubmitting.value = false } }
async function deletePlayer(player: AdminPlayer) { if (!window.confirm(`Delete ${player.full_name}? This also removes their attendance and parent links.`)) return; deletingPlayerId.value = player.id; try { await $fetch(`/api/admin/players/${player.id}`, { method: 'DELETE' }); if (selectedPlayerId.value === player.id) resetForm(); await refresh(); pageSuccess.value = 'Player deleted.' } catch (error) { report(error, 'Unable to delete the player.') } finally { deletingPlayerId.value = null } }
function formatDate(value: string) { return new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium' }).format(new Date(`${value}T00:00:00`)) }
watch(activeTeams, value => { if (!form.team_id && value[0]) form.team_id = value[0].id }, { immediate: true })
</script>
<template><div class="mx-auto max-w-7xl space-y-6"><div class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p class="eyebrow text-brand-700">Admin area</p><h1>Players</h1><p class="text-body text-[color:var(--color-text-secondary)]">Create, edit, and remove player records.</p></div><Button class="gap-2" @click="resetForm"><Plus class="h-4 w-4" />Create player</Button></div><div v-if="pageSuccess" class="rounded-lg bg-[var(--status-confirmed-bg)] px-4 py-3 text-sm">{{ pageSuccess }}</div><div v-if="pageError" class="rounded-lg bg-[var(--status-declined-bg)] px-4 py-3 text-sm">{{ pageError }}</div><div class="grid gap-6 xl:grid-cols-[minmax(0,1.45fr)_minmax(320px,0.9fr)]"><div class="space-y-6"><Card class="grid gap-3 md:grid-cols-3"><div class="md:col-span-2"><Label for="player-search">Search players</Label><Input id="player-search" v-model="searchInput" /></div><div><Label for="team-filter">Team</Label><select id="team-filter" v-model="teamFilter" :class="selectClass"><option value="all">All teams</option><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></div></Card><Card class="overflow-hidden p-0"><div class="flex justify-between border-b border-border p-4"><h2>Roster</h2><Badge variant="secondary">{{ pending ? 'Refreshing' : `${players.length} players` }}</Badge></div><div v-for="player in players" :key="player.id" class="flex flex-col gap-4 border-b border-border p-4 sm:flex-row sm:items-center sm:justify-between"><NuxtLink :to="`/admin/players/${player.id}`" class="flex items-start gap-3 hover:text-brand-700"><div class="flex h-11 w-11 items-center justify-center rounded-full bg-brand-50 text-brand-700"><UserRound class="h-5 w-5" /></div><div><p class="font-medium">{{ player.full_name }}{{ player.shirt_number ? ` · #${player.shirt_number}` : '' }}</p><p class="text-sm text-[color:var(--color-text-secondary)]">{{ player.team.name }} · Born {{ formatDate(player.date_of_birth) }}</p></div></NuxtLink><div class="flex gap-2"><Button variant="outline" size="sm" @click="editPlayer(player)"><Pencil class="h-4 w-4" />Edit</Button><Button variant="destructive" size="sm" :disabled="deletingPlayerId === player.id" @click="deletePlayer(player)"><Trash2 class="h-4 w-4" />{{ deletingPlayerId === player.id ? 'Deleting...' : 'Delete' }}</Button></div></div><p v-if="!pending && !players.length" class="p-8 text-center text-sm">No players match the current filters.</p></Card></div><Card class="h-fit space-y-4"><h2>{{ isCreateMode ? 'Create player' : 'Edit player' }}</h2><form class="space-y-4" @submit.prevent="submitForm"><div><Label for="player-name">Full name</Label><Input id="player-name" v-model="form.full_name" required /></div><div><Label for="shirt-number">Shirt number</Label><Input id="shirt-number" v-model="form.shirt_number" type="number" min="1" max="99" /></div><div><Label for="date-of-birth">Date of birth</Label><Input id="date-of-birth" v-model="form.date_of_birth" type="date" required /></div><div><Label for="player-team">Team</Label><select id="player-team" v-model="form.team_id" :class="selectClass" required><option value="" disabled>Select team</option><option v-for="team in activeTeams" :key="team.id" :value="team.id">{{ team.name }}</option></select></div><label class="flex gap-3"><input v-model="form.is_active" type="checkbox">Active player</label><div class="flex gap-3"><Button type="submit" :disabled="isSubmitting || !activeTeams.length">{{ isSubmitting ? 'Saving...' : isCreateMode ? 'Create player' : 'Save changes' }}</Button><Button type="button" variant="outline" @click="resetForm">Clear</Button></div></form></Card></div></div></template>
